require_once __DIR__.'/../includes/auth.php';requireLogin();if(!canManageNews()){http_response_code(403);exit('غير مصرح.');}$errors=[];
if(isPost()){verifyCsrf();$title=trim($_POST['title']??'');$summary=trim($_POST['summary']??'');$details=sanitizeHtml($_POST['details']??'');$cat=(int)($_POST['category_id']??0);$status=$_POST['status']??'draft';if(currentUser()['role']==='author'&&!in_array($status,['draft','pending'],true))$status='draft';if(!in_array($status,['draft','pending','published','archived'],true))$status='draft';if(mb_strlen($title)<5)$errors[]='عنوان الخبر قصير جدًا.';if(!$cat)$errors[]='اختر تصنيفًا.';try{$image=uploadImage('image');}catch(RuntimeException $x){$errors[]=$x->getMessage();}$published=$status==='published'?date('Y-m-d H:i:s'):null;if(!$errors){$s=db()->prepare('INSERT INTO news(title,slug,summary,details,image,category_id,user_id,status,is_featured,is_breaking,views_count,seo_title,seo_description,published_at,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,0,?,?,?,NOW(),NOW())');$s->execute([$title,uniqueSlug('news',$title),$summary,$details,$image,$cat,currentUser()['id'],$status,!empty($_POST['is_featured'])?1:0,!empty($_POST['is_breaking'])?1:0,trim($_POST['seo_title']??''),trim($_POST['seo_description']??''),$published]);flash('success','تم إنشاء الخبر بنجاح.');redirect(url('admin/news.php'));}}
